  geom_hline(yintercept = c(ucl_wafer, lcl_wafer), color = "firebrick", linetype = "dashed") +
  scale_x_continuous(breaks = seq(1, 25, 2)) +
  labs(title = "Control Chart for Counts", x = "Wafer", y = "Defects") +
  theme_light() +
  theme(plot.title = element_text(hjust = 0.5))
```

