library(tidyverse)

N <- 3
suppliers2 <- tibble(
  Supplier = 1:12,
  Amount = c(9, 8, 9, 12, 9, 12, 11, 7, 13, 9, 11, 10)
) |>
  mutate(
    MA = as.numeric(stats::filter(Amount, rep(1 / N, N), sides = 1)),
    Error = Amount - MA,
    `Error squared` = Error^2
  )

suppliers2 |>
  mutate(across(c(MA, Error, `Error squared`), ~ ifelse(is.na(.x), "", sprintf("%.3f", .x)))) |>
  knitr::kable(align = "rrrrr")
```

